'use strict';
// Real external stdio agent -> MCP -> authenticated HTTP -> native APP mutex -> core Writer.
// Fixture is generated by fb-app's synthetic example; no installed desktop or real books.
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const {spawn}=require('node:child_process');
const {createInterface}=require('node:readline');
const {randomUUID}=require('node:crypto');
const {create}=require('../main/ai-transport.cjs');
const {api}=require('../agent/mcp.cjs');
const fixture=JSON.parse(fs.readFileSync(path.join(process.argv[2],'fixture.json')));
const native=require(path.resolve(process.argv[3]));
let client,server,checks=0;
function pass(message){console.log(`PASS ${++checks}: ${message}`);}
(async()=>{
  native.openBook(fixture.book,fixture.key_hex);
  const signIn=()=>{
    const page=JSON.parse(native.render('/desktop/sign-in/'));
    const token=/name="fb_command_token" value="([0-9a-f]{64})"/.exec(page.html)[1];
    const result=JSON.parse(native.run(JSON.stringify({type:'SubmitForm',path:'/desktop/sign-in/',token,fields:[['action','signin'],['username',fixture.username],['password',fixture.user_password]]})));
    assert.equal(result.outcome,'redirect');assert.equal(JSON.parse(native.appState()).signed_in,true);
  };
  signIn();
  const g=JSON.parse(native.aiGrant(fixture.company_id,'Synthetic external MCP', 'accounting_write'));
  server=create({generation:()=>native.aiGeneration(),request:(token,body)=>native.aiRequestAsync(token,body)});
  const endpoint=await server.start();
  const config={endpoint,token:g.token};
  client=spawn(process.execPath,['-e',`require(${JSON.stringify(path.resolve(__dirname,'../agent/mcp.cjs'))}).serve(JSON.parse(process.env.FB_SYNTHETIC_MCP));`],{env:{...process.env,FB_SYNTHETIC_MCP:JSON.stringify(config)},stdio:['pipe','pipe','pipe']});
  let seq=0,stderr='';const pending=new Map();
  client.stderr.on('data',c=>stderr+=c);
  createInterface({input:client.stdout}).on('line',line=>{const r=JSON.parse(line);const p=pending.get(r.id);if(p){pending.delete(r.id);p(r);}});
  const rpc=(method,params)=>new Promise((resolve,reject)=>{const id=++seq;const deadline=setTimeout(()=>{pending.delete(id);reject(new Error('Synthetic MCP request timeout'));},15000);pending.set(id,v=>{clearTimeout(deadline);resolve(v);});client.stdin.write(JSON.stringify({jsonrpc:'2.0',id,method,params})+'\n');});
  const call=async(name,args={})=>{
    const r=await rpc('tools/call',{name,arguments:args});
    assert.equal(r.result?.isError,false,JSON.stringify(r));return JSON.parse(r.result.content[0].text);
  };
  assert.equal((await rpc('initialize',{protocolVersion:'2025-06-18',capabilities:{},clientInfo:{name:'synthetic-test',version:'1'}})).result.protocolVersion,'2025-06-18');
  const tools=(await rpc('tools/list',{})).result.tools;
  assert.ok(tools.length>70);assert.ok(tools.find(t=>t.name==='app_ImportPreview').inputSchema.$defs.Journal);
  pass(`External MCP process discovers ${tools.length} concrete operation schemas`);
  const customer=(await call('command_SaveCustomer',{display_name:'Synthetic MCP customer'})).data.id;
  const values={request_key:randomUUID(),customer_id:customer,date:'2026-11-02',tax_mode:'NONE',lines:[{description:'MCP service',quantity:'2',rate:'45.67',income_account_id:fixture.income}]};
  const created=await call('command_SaveInvoice',{values});
  const invoice=await call('app_Invoice',{invoice_id:created.data.id});
  await call('command_PostInvoice',{invoice_id:created.data.id,expected_revision:invoice.revision});
  assert.match(JSON.stringify(await call('query_Invoices')),/91\.34/);
  pass('MCP creates and posts a real 91.34 invoice with revision/review validation');
  const pendingFeed=await call('app_PendingFeed');assert.equal(pendingFeed.total,1);
  await call('app_SuggestFeed',{transaction_id:pendingFeed.items[0].id});
  const feed=await call('app_AcceptFeed',{transaction_id:pendingFeed.items[0].id,category:{kind:'JOURNAL',account_id:fixture.expense,payee_name:'Synthetic vendor'}});
  assert.equal(feed.status,'ACCEPTED');
  assert.equal((await call('app_PendingFeed')).total,0);
  pass('MCP lists, categorizes and accepts the staged feed through the accounting service');
  const journals=[{request_key:randomUUID(),date:'2026-11-03',memo:'MCP import',lines:[{account:fixture.expense,debit:'20.03',credit:'0.00',description:'Office',name:''},{account:fixture.bank,debit:'0.00',credit:'20.03',description:'Bank',name:''}]}];
  const before=await call('query_Register',{account_id:fixture.bank});
  const preview=await call('app_ImportPreview',{journals});
  assert.deepEqual(await call('query_Register',{account_id:fixture.bank}),before);
  const applied=await call('app_ImportApply',{preview_token:preview.preview_token});
  assert.deepEqual(applied,await call('app_ImportApply',{preview_token:preview.preview_token}));
  assert.notEqual((await call('query_Register',{account_id:fixture.bank})).closing,before.closing);
  const balance=await call('app_TrialBalance',{as_of:'2026-12-31'});assert.equal(balance.debit,balance.credit);
  pass('MCP preview rolls back; apply posts exactly once and trial balance remains balanced');
  const retry={...values,request_key:randomUUID(),memo:'Concurrent stable retry'};
  const attempts=await Promise.allSettled(Array.from({length:3},()=>Promise.resolve().then(()=>native.aiRequestAsync(g.token,JSON.stringify({operation:'command_SaveInvoice',arguments:{values:retry}})))));
  const results=attempts.filter(r=>r.status==='fulfilled').map(r=>JSON.parse(r.value));
  assert.ok(results.length>=1);assert.ok(attempts.filter(r=>r.status==='rejected').every(r=>/BUSY/.test(r.reason.message)));
  assert.equal(new Set(results.map(r=>r.data.id)).size,1);
  pass('Concurrent native agent tasks serialize under the APP mutex and preserve request-key idempotency');
  const concurrent=await Promise.allSettled(Array.from({length:3},()=>api(config,'/v1/call',{operation:'command_SaveInvoice',arguments:{values:retry}})));
  const successes=concurrent.filter(r=>r.status==='fulfilled');assert.ok(successes.length>=1);assert.ok(successes.every(r=>r.value.data.id===results[0].data.id));
  const readonly=JSON.parse(native.aiGrant(fixture.company_id,'Synthetic reader','read_only'));
  await assert.rejects(api({endpoint,token:readonly.token},'/v1/call',{operation:'command_SaveCustomer',arguments:{display_name:'forbidden'}}));
  const forged=await rpc('tools/call',{name:'query_Accounts',arguments:{company_id:fixture.other_company_id}});assert.equal(forged.result.isError,true);
  const audit=JSON.stringify(await call('app_AuditHistory',{limit:100}));
  assert.ok(audit.includes('Synthetic operator') && audit.includes('Synthetic external MCP') && audit.includes(g.id));
  assert.ok(!audit.includes(g.token));assert.ok(!stderr.includes(g.token));
  pass('Read-only and forged scopes fail; append-only audit links the real operator and external connection without keys');
  native.aiRevoke(g.id);
  assert.equal((await rpc('tools/call',{name:'query_Accounts',arguments:{}})).result.isError,true);
  native.lock();native.openBook(fixture.book,fixture.key_hex);
  signIn();
  await assert.rejects(api({endpoint,token:readonly.token},'/v1/catalogue'));
  pass('Revocation and lock/reopen invalidate old external credentials');
  client.stdin.end();
})().catch(error=>{console.error(error);process.exitCode=1;}).finally(async()=>{if(client)client.kill();if(server)await server.stop();try{native.lock();}catch{}});
